// 解析前端发来的请求
const query = $input.item.json.query || '';
const imageUrl = $input.item.json.image_url || '';

return {
  query: query,
  imageUrl: imageUrl,
  hasImage: imageUrl && imageUrl.length > 0
};

// 意图分类：基于规则快速判断，避免 LLM 调用延迟
const query = $input.item.json.query || '';
const q = query.toLowerCase();

let intent = 'help';
let isbn = '';
let bookTitle = '';

// 场景1: 直接输入 ISBN (10或13位数字)
const isbnMatch = query.match(/(?:97[89])?\d{9}[\dXx]/i);
if (isbnMatch) {
  intent = 'single_entry';
  isbn = isbnMatch[0].replace(/[^\dXx]/gi, '');
}
// 场景2: 信息补全关键词
else if (/补全|缺失|不全|完善|补充/.test(q)) {
  intent = 'enrich';
  // 提取书名
  const titleMatch = query.match(/《(.+?)》/);
  if (titleMatch) bookTitle = titleMatch[1];
}
// 场景3: 查询不完整图书
else if (/哪些.*不全|列出.*不全|扫描.*不全|不完整/.test(q)) {
  intent = 'enrich';
}
// 场景4: 批量导入
else if (/批量|导入|Excel|文件|多本/.test(q)) {
  intent = 'batch_import';
}
// 场景5: 录入/添加
else if (/录入|添加|新书|录入这|帮我.*录入/.test(q)) {
  intent = 'single_entry';
}
// 场景6: 查询
else if (/查询|搜索|找/.test(q)) {
  intent = 'single_entry';
}

return {
  intent: intent,
  isbn: isbn,
  bookTitle: bookTitle,
  originalQuery: query,
  hasImage: $input.item.json.hasImage || false
};

// 构建 ISBN 查询请求
const isbn = $input.item.json.isbn;
const query = $input.item.json.originalQuery;

// 如果有 ISBN，直接查询
if (isbn) {
  return {
    url: 'http://localhost:8000/api/smart-entry/isbn-lookup',
    method: 'POST',
    body: { isbn: isbn },
    isbn: isbn
  };
}

// 没有 ISBN：引导用户提供
return {
  noIsbn: true,
  reply: '请提供图书的 ISBN 编号（10位或13位数字），或上传封面照片以便我识别 ISBN。\n\n例如：\n- 直接输入 ISBN：9787549021680\n- 上传封面/条形码图片'
};

// 检查是否有 ISBN
if ($input.item.json.noIsbn) {
  return { skip: true, reply: $input.item.json.reply };
}
return $input.item.json;

// 格式化查询结果
const resp = $input.item.json;

if (!resp.success) {
  return {
    reply: `📚 未找到 ISBN 信息\n\n${resp.message || '该 ISBN 在豆瓣、Google Books、OpenLibrary 均未找到匹配的图书。'}\n\n建议：\n1. 确认 ISBN 是否正确\n2. 手动录入图书信息\n3. 重新拍摄封面照片`
  };
}

const book = resp.data || {};
const source = resp.source === 'douban' ? '豆瓣' : resp.source === 'google_books' ? 'Google Books' : 'OpenLibrary';

let reply = `📚 找到以下图书信息（来源：${source}）\n\n`;
reply += `**《${book.title || '未知书名'}》**\n`;
if (book.author) reply += `- 作者：${book.author}\n`;
if (book.publisher) reply += `- 出版社：${book.publisher}\n`;
if (book.publish_date) reply += `- 出版日期：${book.publish_date}\n`;
if (book.pages) reply += `- 页数：${book.pages}\n`;
if (book.price) reply += `- 定价：${book.price}\n`;
if (book.binding) reply += `- 装帧：${book.binding}\n`;
if (book.rating) reply += `- 评分：${book.rating}/10\n`;
if (book.series) reply += `- 丛书：${book.series}\n`;
if (book.translator) reply += `- 译者：${book.translator}\n`;
if (book.summary) reply += `- 简介：${book.summary.substring(0, 200)}${book.summary.length > 200 ? '...' : ''}\n`;

reply += `\n✅ 系统已自动填充录入表单，你可以去前端页面点击「确认录入」保存。`;

return { reply: reply };

// 检查用户是想列出不完整的书还是补全特定书
const query = $input.item.json.originalQuery || '';
const bookTitle = $input.item.json.bookTitle || '';

// 有具体书名 → 先搜索找到 book_id，再补全
if (bookTitle) {
  return {
    action: 'enrich_specific',
    bookTitle: bookTitle,
    url: 'http://localhost:8000/api/smart-entry/missing-books',
    method: 'GET'
  };
}

// 列出不完整的书
return {
  action: 'list_missing',
  url: 'http://localhost:8000/api/smart-entry/missing-books',
  method: 'GET'
};

const resp = $input.item.json;
const action = $('code-prepare-enrich').item.json.action;
const bookTitle = $('code-prepare-enrich').item.json.bookTitle || '';

// 列出缺失列表
if (action === 'list_missing') {
  const books = resp.books || [];
  if (books.length === 0) {
    return { reply: '✅ 所有馆藏图书信息已完整，无需补全！' };
  }

  let reply = `📊 找到 **${resp.total || books.length}** 本信息不完整的图书：\n\n`;
  const top10 = books.slice(0, 10);
  for (const b of top10) {
    const missing = (b.missing_fields || []).map(f => {
      const names = { title:'书名', author:'作者', publisher:'出版社', publish_date:'出版日期', pages:'页数', price:'定价', binding:'装帧', rating:'评分', summary:'简介', cover_url:'封面', original_title:'原作名', series:'丛书', translator:'译者' };
      return names[f] || f;
    }).join('、');
    reply += `- **《${b.title || '(无书名)'}》** 完整度 ${b.completeness}% | 缺失: ${missing}\n`;
  }
  if (books.length > 10) reply += `\n... 还有 ${books.length - 10} 本\n`;
  reply += `\n💡 告诉我你想补全哪本书，例如："帮我把《${top10[0]?.title || 'XXX'}》补全" 或 "全部补全"`;
  return { reply: reply };
}

// 指定书名 → 找到 book_id
if (action === 'enrich_specific') {
  const books = resp.books || [];
  const matched = books.find(b => (b.title || '').includes(bookTitle) || bookTitle.includes(b.title || ''));
  if (!matched) {
    return { 
      reply: `未找到匹配的图书 "${bookTitle}"，请确认书名是否准确。\n\n你可以说"列出不完整的书"查看所有需要补全的图书。`,
      action: 'not_found'
    };
  }
  return {
    action: 'enrich',
    bookId: matched.book_id,
    bookTitle: matched.title,
    url: `http://localhost:8000/api/smart-entry/enrich/${matched.book_id}`,
    method: 'POST'
  };
}

return { reply: '请告诉我想做什么：列出不完整的书，或指定书名进行补全。' };

// 检查是否需要继续调用 enrich API
if ($input.item.json.action === 'not_found' || !$input.item.json.url) {
  return { skip: true, reply: $input.item.json.reply || '' };
}
if ($input.item.json.action !== 'enrich') {
  return { skip: true, reply: $input.item.json.reply || '' };
}
return $input.item.json;

const resp = $input.item.json;
const bookTitle = $('code-format-missing').item.json.bookTitle || '';

if (!resp.success) {
  return {
    reply: `❌ 补全失败\n\n${resp.message || '无法补全该书的信息。'}\n\n可能原因：\n- 该书无 ISBN，无法自动查询\n- 外部数据源未收录此 ISBN`
  };
}

let reply = `✅ 《${bookTitle}》信息已补全！\n\n`;
if (resp.filled_fields && resp.filled_fields.length > 0) {
  reply += `已填充字段：${resp.filled_fields.join('、')}\n`;
}
if (resp.skipped_fields && resp.skipped_fields.length > 0) {
  reply += `跳过字段：${resp.skipped_fields.join('、')}\n`;
}
reply += `完整度：${resp.completeness}%\n`;
if (resp.lookup_source) {
  reply += `数据来源：${resp.lookup_source}`;
}
return { reply: reply };

return {
  reply: `📋 **批量导入流程**

1. 📥 访问前端的「批量导入」页面（/import）
2. 📋 下载导入模板（Excel 格式）
3. ✍️ 在模板中填写 ISBN 列表
4. 📤 上传文件，系统自动解析并同步豆瓣数据
5. ✨ 导入完成后，回到这里说"帮我补全"，自动补充缺失信息

💡 **提示**：系统支持 .xlsx / .xls / .csv / .txt 格式，文件需包含 ISBN 列。`
};

const query = $input.item.json.originalQuery || '';

let reply = `👋 你好！我是智能录入助手，可以帮你：

`;
reply += `📷 **单本录入** — 输入 ISBN 直接查询图书信息并自动填充录入表单
`;
reply += `✨ **信息补全** — 检测馆藏中不完整的图书并自动补全缺失信息
`;
reply += `📋 **批量导入** — 通过 Excel 批量导入 ISBN 列表

`;
reply += `试试这些：
- 输入 ISBN：9787549021680
- "有哪些书信息不全？"
- "我要批量导入"`;

return { reply: reply };

// 从所有分支收集回复
const items = $input.all();
for (const item of items) {
  if (item.json && item.json.reply && !item.json.skip) {
    return { reply: item.json.reply };
  }
}
// Fallback
return { reply: '收到你的消息，但我暂时无法处理。请尝试：\n- 输入 ISBN 编号查询图书\n- "有哪些书信息不全？" 查看补全列表\n- "帮我录入" 开始录入' };
